import{_t as e,it as t,n,rt as r}from"./chunks/framework.CJEq1BAB.js";var i=JSON.parse(`{"title":"Roles and permissions","description":"","frontmatter":{"title":"Roles and permissions","covers":{"screens":[],"stories":["US-143","US-147"]}},"headers":[],"relativePath":"administration/roles-and-permissions.md","filePath":"administration/roles-and-permissions.md"}`),a={name:`administration/roles-and-permissions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to “Roles and permissions”">​</a></h1><p>Every operation of OEA requires a permission, and permissions come only from roles. OEA ships a fixed permission catalog and built-in roles; <code>GET /admin/permissions</code> and <code>GET /admin/roles</code> return them.</p><h2 id="built-in-roles" tabindex="-1">Built-in roles <a class="header-anchor" href="#built-in-roles" aria-label="Permalink to “Built-in roles”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Permissions</th><th>For</th></tr></thead><tbody><tr><td><code>portal-reader</code></td><td><code>portal:read</code></td><td>reading shared content in the portal</td></tr><tr><td><code>viewer</code></td><td><code>portal:read</code>, <code>entity:read</code></td><td>reading the repository</td></tr><tr><td><code>analyst</code></td><td><code>viewer</code> + <code>analytics:query</code></td><td>analytics queries</td></tr><tr><td><code>enterprise-architect</code></td><td><code>viewer</code> + <code>entity:write</code>, <code>entity:delete</code>, <code>entity:restore</code>, <code>catalog:manage</code>, <code>dashboard:manage</code>, <code>viewpoint:manage</code>, <code>plateau:go-live</code>, <code>webhook:manage</code></td><td>maintaining the architecture</td></tr><tr><td><code>integration-writer</code></td><td><code>entity:read</code>, <code>entity:write</code></td><td>integrations that write entities</td></tr><tr><td><code>auditor</code></td><td><code>audit:read</code></td><td>reading and verifying the audit log</td></tr><tr><td><code>metamodel-admin</code></td><td><code>metamodel:write</code></td><td>changing and importing the metamodel</td></tr><tr><td><code>security-admin</code></td><td><code>visibility:configure</code>, <code>visibility-scope:assign</code>, <code>role:assign</code>, <code>person:manage</code></td><td>visibility rules, persons and roles</td></tr><tr><td><code>system-admin</code></td><td><code>role:assign</code>, <code>person:manage</code>, <code>service-account:manage</code>, <code>auth-config:manage</code>, <code>settings:manage</code></td><td>administering the instance</td></tr></tbody></table><p>The local system admin account holds the role <code>system-admin</code>. <strong>Privileged roles</strong> – roles with an admin-class permission (<code>metamodel:write</code>, <code>visibility:configure</code>, <code>visibility-scope:assign</code>, <code>role:assign</code>, <code>person:manage</code>, <code>service-account:manage</code>, <code>auth-config:manage</code>, <code>settings:manage</code>) – are effective only in a session confirmed with a second factor. For a login through an identity provider, the provider has to report the second factor in <code>amr</code>.</p><h2 id="grant-roles-through-idp-groups" tabindex="-1">Grant roles through IdP groups <a class="header-anchor" href="#grant-roles-through-idp-groups" aria-label="Permalink to “Grant roles through IdP groups”">​</a></h2><p>You grant roles by mapping a group of the identity provider to a role. Every person in that group gets the role at their next login:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">authProviderId</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROVIDER</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">groupIdentifier</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;group-uuid&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">roleId</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">viewer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/idp-group-mappings&quot;</span></span></code></pre></div><ul><li>The group identifier must be the immutable UUID of the group (the group object ID of Entra ID, Authentik and Keycloak); display names are rejected with <code>422</code>.</li><li>A person cannot map a group that is contained in their own groups claim (separation of duties).</li><li><code>GET /admin/idp-group-mappings</code> lists the mappings; <code>PUT</code> and <code>DELETE /admin/idp-group-mappings/{mappingId}</code> change and remove one.</li><li>Like the first identity binding, the first group mapping ends the setup phase.</li></ul><h2 id="when-group-membership-changes" tabindex="-1">When group membership changes <a class="header-anchor" href="#when-group-membership-changes" aria-label="Permalink to “When group membership changes”">​</a></h2><p>OEA re-evaluates the group membership with the refresh token of the provider at the latest 15 minutes after the previous evaluation: if you remove a person from a group at the provider, the derived role is gone within 15 minutes. Without a refresh token, with an unreachable provider, or with a missing or truncated groups claim, no IdP-derived role applies (audit event <code>auth.idp-groups-unusable</code>).</p><p>A session established through an identity provider ends at the first of: 30 minutes without activity, 12 hours after the login, or the expiry or rejection of the refresh token. OEA never extends a token of the provider.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};